function abbreviateProduct(left: number, right: number): string {
    let product = BigInt(1);
    let count2 = 0;
    let count5 = 0;

    for (let value = left; value <= right; value++) {
        let current = value;

        while (current % 2 === 0) {
            current /= 2;
            count2++;
        }

        while (current % 5 === 0) {
            current /= 5;
            count5++;
        }

        product *= BigInt(current);
    }

    const trailingZeros = Math.min(count2, count5);
    count2 -= trailingZeros;
    count5 -= trailingZeros;

    const power = (base: number, exponent: number): bigint => {
        let result = BigInt(1);
        let current = BigInt(base);

        while (exponent > 0) {
            if (exponent % 2 === 1) {
                result *= current;
            }
            current *= current;
            exponent = Math.floor(exponent / 2);
        }

        return result;
    };

    if (count2 > 0) {
        product *= power(2, count2);
    } else if (count5 > 0) {
        product *= power(5, count5);
    }

    const digits = product.toString();

    if (digits.length <= 10) {
        return `${digits}e${trailingZeros}`;
    }

    return `${digits.slice(0, 5)}...${digits.slice(-5)}e${trailingZeros}`;
};
