function ambiguousCoordinates(s: string): string[] {
    const digits = s.slice(1, -1);
    const result: string[] = [];

    function generate(part: string): string[] {
        const numbers: string[] = [];

        if (part.length === 1 || part[0] !== "0") {
            numbers.push(part);
        }

        for (let i = 1; i < part.length; i++) {
            const integerPart = part.slice(0, i);
            const fractionalPart = part.slice(i);

            const validInteger =
                integerPart.length === 1 || integerPart[0] !== "0";
            const validFraction = fractionalPart[fractionalPart.length - 1] !== "0";

            if (validInteger && validFraction) {
                numbers.push(`${integerPart}.${fractionalPart}`);
            }
        }

        return numbers;
    }

    for (let i = 1; i < digits.length; i++) {
        const leftNumbers = generate(digits.slice(0, i));
        const rightNumbers = generate(digits.slice(i));

        for (const left of leftNumbers) {
            for (const right of rightNumbers) {
                result.push(`(${left}, ${right})`);
            }
        }
    }

    return result;
};
