function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const frequency = (s: string): number => {
        let smallest = s[0];
        let count = 1;

        for (let i = 1; i < s.length; i++) {
            if (s[i] < smallest) {
                smallest = s[i];
                count = 1;
            } else if (s[i] === smallest) {
                count++;
            }
        }

        return count;
    };

    const wordFrequencies = words.map(frequency).sort((a, b) => a - b);

    return queries.map(query => {
        const queryFrequency = frequency(query);
        let left = 0;
        let right = wordFrequencies.length;

        while (left < right) {
            const middle = left + Math.floor((right - left) / 2);

            if (wordFrequencies[middle] <= queryFrequency) {
                left = middle + 1;
            } else {
                right = middle;
            }
        }

        return wordFrequencies.length - left;
    });
};
