function countVowelSubstrings(word: string): number {
    const lastSeen: Record<string, number> = {
        a: -1,
        e: -1,
        i: -1,
        o: -1,
        u: -1
    };

    let lastConsonant = -1;
    let count = 0;

    for (let i = 0; i < word.length; i++) {
        const char = word[i];

        if (char in lastSeen) {
            lastSeen[char] = i;

            const earliestVowel = Math.min(
                lastSeen.a,
                lastSeen.e,
                lastSeen.i,
                lastSeen.o,
                lastSeen.u
            );

            if (earliestVowel > lastConsonant) {
                count += earliestVowel - lastConsonant;
            }
        } else {
            lastConsonant = i;
        }
    }

    return count;
};
