function canCross(stones: number[]): boolean {
    const n = stones.length;

    if (stones[1] !== 1) {
        return false;
    }

    const indexByPosition = new Map<number, number>();
    for (let i = 0; i < n; i++) {
        indexByPosition.set(stones[i], i);

        if (i > 0 && stones[i] - stones[i - 1] > i) {
            return false;
        }
    }

    const reachable: Array<Set<number> | undefined> = new Array(n);
    reachable[1] = new Set([1]);

    for (let i = 1; i < n; i++) {
        const jumps = reachable[i];
        if (jumps === undefined) {
            continue;
        }

        for (const lastJump of jumps) {
            for (let nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
                if (nextJump <= 0) {
                    continue;
                }

                const nextPosition = stones[i] + nextJump;
                const nextIndex = indexByPosition.get(nextPosition);

                if (nextIndex === undefined) {
                    continue;
                }

                if (nextIndex === n - 1) {
                    return true;
                }

                if (reachable[nextIndex] === undefined) {
                    reachable[nextIndex] = new Set<number>();
                }
                reachable[nextIndex]!.add(nextJump);
            }
        }
    }

    return n === 2;
}
