function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
    const reachable = fruits.filter(
        ([position]) => position >= startPos - k && position <= startPos + k
    );

    let left = 0;
    let currentSum = 0;
    let maximum = 0;

    const stepsNeeded = (leftPosition: number, rightPosition: number): number => {
        if (rightPosition <= startPos) {
            return startPos - leftPosition;
        }

        if (leftPosition >= startPos) {
            return rightPosition - startPos;
        }

        const leftDistance = startPos - leftPosition;
        const rightDistance = rightPosition - startPos;

        return Math.min(
            2 * leftDistance + rightDistance,
            leftDistance + 2 * rightDistance
        );
    };

    for (let right = 0; right < reachable.length; right++) {
        currentSum += reachable[right][1];

        while (
            left <= right &&
            stepsNeeded(reachable[left][0], reachable[right][0]) > k
        ) {
            currentSum -= reachable[left][1];
            left++;
        }

        maximum = Math.max(maximum, currentSum);
    }

    return maximum;
}
