function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    flowers.sort((a, b) => a - b);

    let incompleteCount = 0;
    while (incompleteCount < flowers.length && flowers[incompleteCount] < target) {
        incompleteCount++;
    }

    const prefix: number[] = new Array(incompleteCount + 1).fill(0);
    for (let i = 0; i < incompleteCount; i++) {
        prefix[i + 1] = prefix[i] + flowers[i];
    }

    let answer = 0;
    let completionCost = 0;

    for (let completed = 0; completed <= incompleteCount; completed++) {
        if (completionCost > newFlowers) break;

        const remaining = incompleteCount - completed;
        let beauty = (flowers.length - remaining) * full;

        if (remaining > 0) {
            const budget = newFlowers - completionCost;

            let left = 0;
            let right = remaining - 1;
            let index = 0;

            while (left <= right) {
                const mid = Math.floor((left + right) / 2);
                const cost = flowers[mid] * (mid + 1) - prefix[mid + 1];

                if (cost <= budget) {
                    index = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            const levelingCost =
                flowers[index] * (index + 1) - prefix[index + 1];

            const minimum = Math.min(
                target - 1,
                flowers[index] +
                    Math.floor((budget - levelingCost) / (index + 1))
            );

            beauty += minimum * partial;
        }

        answer = Math.max(answer, beauty);

        if (completed < incompleteCount) {
            completionCost += target - flowers[incompleteCount - 1 - completed];
        }
    }

    return answer;
}
