    function solve(start: number, end: number): number {
        let prevTwo = new Array<number>(picks + 1).fill(Number.NEGATIVE_INFINITY);
        let prevOne = new Array<number>(picks + 1).fill(Number.NEGATIVE_INFINITY);
        prevTwo[0] = 0;
        prevOne[0] = 0;

