function isSolvable(words: string[], result: string): boolean {
    const mapping = new Array<number>(26).fill(-1);
    const leading = new Array<boolean>(26).fill(false);
    const seen = new Set<string>();

    let maxLength = 0;

    for (const word of words) {
        maxLength = Math.max(maxLength, word.length);
        if (word.length > 1) {
            leading[word.charCodeAt(0) - 65] = true;
        }
        for (const char of word) seen.add(char);
    }

    if (result.length > 1) {
        leading[result.charCodeAt(0) - 65] = true;
    }
    for (const char of result) seen.add(char);

    if (seen.size > 10) return false;
    if (result.length < maxLength || result.length > maxLength + 1) {
        return false;
    }

    let usedMask = 0;

    const dfs = (column: number, row: number, sum: number): boolean => {
        if (column === result.length) {
            return sum === 0;
        }

        if (row < words.length) {
            const word = words[row];

            if (column >= word.length) {
                return dfs(column, row + 1, sum);
            }

            const letter = word.charCodeAt(word.length - 1 - column) - 65;
            const assignedDigit = mapping[letter];

            if (assignedDigit !== -1) {
                return dfs(column, row + 1, sum + assignedDigit);
            }

            for (let digit = 0; digit <= 9; digit++) {
                const bit = 1 << digit;

                if ((usedMask & bit) !== 0) continue;
                if (digit === 0 && leading[letter]) continue;

                mapping[letter] = digit;
                usedMask |= bit;

                if (dfs(column, row + 1, sum + digit)) return true;

                mapping[letter] = -1;
                usedMask &= ~bit;
            }

            return false;
        }

        const resultLetter =
            result.charCodeAt(result.length - 1 - column) - 65;
        const requiredDigit = sum % 10;
        const carry = Math.floor(sum / 10);
        const assignedDigit = mapping[resultLetter];

        if (assignedDigit !== -1) {
            if (assignedDigit !== requiredDigit) return false;
            return dfs(column + 1, 0, carry);
        }

        const bit = 1 << requiredDigit;

        if ((usedMask & bit) !== 0) return false;
        if (requiredDigit === 0 && leading[resultLetter]) return false;

        mapping[resultLetter] = requiredDigit;
        usedMask |= bit;

        if (dfs(column + 1, 0, carry)) return true;

        mapping[resultLetter] = -1;
        usedMask &= ~bit;

        return false;
    };

    return dfs(0, 0, 0);
};
